D=dict
LAMP=lambda x,y,s=1: f'<g transform="translate({x} {y}) scale({s})" stroke="#111" stroke-width="2"><path d="M-14 0 h28 l-4 8 h-20z" fill="#e0a800"/><path d="M0 0 q-8 -16 0 -24 q8 8 0 24z" fill="#ff8c1a"/></g>'
def M(a,b,c,d,n): return [[a,b],[c,d+f' ‖{n}‖']]
V=[
D(n='1',lines=M('śriyaḥ kāntāya','kalyāṇanidhaye nidhaye\'rthinām |','śrīveṅkaṭanivāsāya','śrīnivāsāya maṅgalam',1),theme='MAṄGALAM TO ŚRĪNIVĀSA',
 svg=svg('A devotee waving a lamp before the Lord on the hill, with the word Mangalam glowing',HILL+TEMPLE(150,84)+person(60,140,'#ff8c1a','#f2c79b',.7)+LAMP(84,104,.9)+lab(110,26,'MAṄGALAM!',14),B),
 mean='May all be auspicious for Śrīnivāsa, who dwells on Śrī Veṅkaṭa: the beloved of Śrī, the treasury of all auspicious qualities, the treasure of all who seek.',
 plain='Blessings to Śrīnivāsa of Veṅkaṭa hill: Lakṣmī\'s beloved, full of every good quality, the treasure every seeker looks for.',
 words=[('śriyaḥ kāntāya','<b>to the beloved of Śrī</b>'),('kalyāṇa-nidhaye','<b>treasury of auspicious qualities</b>'),('nidhaye arthinām','<b>treasure of those who seek</b>'),('veṅkaṭa-nivāsāya','<b>who dwells on Veṅkaṭa</b>'),('śrīnivāsāya','<b>to Śrīnivāsa</b>'),('maṅgalam','<b>may it be auspicious</b>')],
 deep='<p><b>Blessing the Lord.</b> The last section turns everything around: instead of asking the Lord to bless us, the devotee blesses the Lord. <i>Maṅgalāśāsana</i> means "wishing auspiciousness" on Him.</p><p><b>Out of love.</b> The Lord needs nothing; but love always wishes the beloved well. The model is Periyāḻvār\'s Tamil <i>Tiruppallāṇḍu</i>, "many years to You!", sung at the start of Śrīvaiṣṇava worship.</p><p><b>Short verses.</b> All 14 verses are in the simple anuṣṭubh metre, and nearly all end <i>maṅgalam</i>: easy to sing together, like a closing chorus.</p>',
 cards=('💡 Maṅgalāśāsana','Wishing auspiciousness to the Lord, out of love.','💡 Tiruppallāṇḍu','Periyāḻvār\'s Tamil hymn wishing the Lord "many, many years".'),
 inner='Love does not only ask; it blesses.',
 talk=('We bless God?','Out of love, yes! Like a mother saying "may you be well" to a grown child. He needs nothing; we wish it anyway.'),
 key='"Maṅgalam": <b>the devotee blesses the Lord</b>.'),
D(n='2',lines=M('lakṣmīsavibhramāloka-','subhrūvibhramacakṣuṣe |','cakṣuṣe sarvalokānāṃ','veṅkaṭeśāya maṅgalam',2),theme='EYES FOR LAKṢMĪ, EYES FOR THE WORLD',
 svg=svg('A large pair of eyes with graceful brows, looking lovingly toward Lakshmi and out over the whole world',
  '<g stroke="#111" stroke-width="2.5"><path d="M30 80 q40 -40 80 0 q-40 40 -80 0z" fill="#fff"/><circle cx="74" cy="80" r="12" fill="#1d3fb8"/><path d="M110 80 q40 -40 80 0 q-40 40 -80 0z" fill="#fff"/><circle cx="154" cy="80" r="12" fill="#1d3fb8"/><path d="M30 50 q40 -20 80 0 M110 50 q40 -20 80 0" fill="none" stroke-width="4"/></g><circle cx="110" cy="140" r="14" fill="#4aa3df" stroke="#111"/>'+lab(110,24,'LOKA-CAKṢUḤ',10),B),
 mean='Maṅgalam to Veṅkaṭeśa: whose eyes, under lovely brows, play in answer to the playful glances of Lakṣmī; who is the eye of all the worlds.',
 plain='Blessings to Veṅkaṭeśa, whose beautiful eyes return Lakṣmī\'s loving glances, and who watches over the whole world.',
 words=[('lakṣmī-savibhrama-āloka','<b>Lakṣmī\'s playful glances</b>'),('su-bhrū','<b>lovely brows</b>'),('vibhrama-cakṣuṣe','<b>whose eyes play</b>'),('cakṣuṣe','<b>to the eye</b>'),('sarva-lokānām','<b>of all the worlds</b>'),('veṅkaṭeśāya','<b>to Veṅkaṭeśa</b>')],
 deep='<p><b>Two kinds of seeing.</b> The same eyes that exchange loving glances with Lakṣmī watch over every world. Private love and universal care are one.</p><p><b>"Eye of the worlds".</b> <i>Cakṣuḥ</i> is a name for the sun, which lets all beings see. The Lord is the light by which the worlds see, and the eye that sees them.</p><p><b>Wordplay.</b> <i>Cakṣuṣe … cakṣuṣe</i>: the word ending line 2 opens line 3, linking the verse like a chain.</p>',
 cards=('💡 Vibhrama','Playful grace, especially of a lover\'s glance.','💡 Loka-cakṣuḥ','"Eye of the world": a name of the sun, used here for the Lord.'),
 inner='The love we give one can be the love we give all.',
 talk=('He\'s looking at Lakṣmī and the world?','Both! The same eyes that love Her watch over every one of us.'),
 key='Eyes for Lakṣmī, <b>an eye for the whole world</b>.'),
D(n='3',lines=M('śrīveṅkaṭādriśṛṅgāgra-','maṅgalābharaṇāṅghraye |','maṅgalānāṃ nivāsāya','śrīnivāsāya maṅgalam',3),theme='HOME OF ALL AUSPICIOUSNESS',
 svg=svg('The Lord\'s feet on top of a hill shining like a jewel',HILL+FEET(110,82,.5)+'<circle cx="110" cy="70" r="40" fill="none" stroke="#ffd60a" stroke-width="3" stroke-dasharray="5 4"/>'+lab(110,24,'MAṄGALA-NIVĀSA',10),B),
 mean='Maṅgalam to Śrīnivāsa: whose feet are the auspicious ornament on the topmost peak of Śrī Veṅkaṭa hill, and who is the dwelling-place of all that is auspicious.',
 plain='Blessings to Śrīnivāsa, whose feet are the jewel on top of Veṅkaṭa hill, and in whom all good things live.',
 words=[('adri-śṛṅga-agra','<b>the tip of the hill\'s peak</b>'),('maṅgala-ābharaṇa','<b>auspicious ornament</b>'),('aṅghraye','<b>whose feet</b>'),('maṅgalānām','<b>of all auspicious things</b>'),('nivāsāya','<b>to the dwelling</b>'),('śrī-nivāsāya','<b>to the dwelling of Śrī</b>')],
 deep='<p><b>Blessing the source of blessing.</b> A charming paradox: we wish <i>maṅgalam</i> to the very one who is the home of all <i>maṅgala</i>.</p><p><b>Two "nivāsas".</b> <i>Maṅgalānāṃ nivāsāya śrīnivāsāya</i>: "to the dwelling of auspiciousness, to the dwelling of Śrī". Lakṣmī and auspiciousness are one.</p><p><b>Echoes.</b> The feet as the hill\'s ornament recall Prapatti verse 13.</p>',
 cards=('💡 Maṅgala','Auspiciousness, well-being, blessing.','💡 Aṅghri','A foot: another word for the Lord\'s feet.'),
 inner='Wish well even to the one who has everything. Love gives anyway.',
 talk=('Blessing the source of all blessings?','Funny, isn\'t it? But that\'s love: we wish Him well even though all good things live in Him.'),
 key='Maṅgalam to <b>the home of all auspiciousness</b>.'),
D(n='4',lines=M('sarvāvayavasaundarya-','sampadā sarvacetasām |','sadā sammohanāyāstu','veṅkaṭeśāya maṅgalam',4),theme='BEAUTY THAT ENCHANTS EVERY HEART',
 svg=svg('People of all kinds gazing up at the Lord, small hearts floating up from them',LORD(110,.9)+crowd(['#ff8c1a','#1d6fb8','#e05a8a','#2a9d6f','#fff'],22,44,150,.4)+''.join(f'<text x="{30+44*k}" y="{90-(k%2)*10}" {F} font-size="14" fill="#e05a8a">♥</text>' for k in range(5)),B),
 mean='May there be maṅgalam for Veṅkaṭeśa, who by the wealth of beauty in every limb always enchants every heart.',
 plain='Blessings to Veṅkaṭeśa, beautiful from head to foot, who wins every heart, always.',
 words=[('sarva-avayava','<b>every limb</b>'),('saundarya-sampadā','<b>by the wealth of beauty</b>'),('sarva-cetasām','<b>of all hearts</b>'),('sadā','<b>always</b>'),('sammohanāya','<b>to the enchanter</b>'),('astu','<b>may there be</b>')],
 deep='<p><b>Head to foot.</b> The Stotram and Prapatti described Him part by part: eyes, chest, feet. This verse sums up: every limb is beautiful.</p><p><b>Enchanting.</b> <i>Sammohana</i>: He captivates every mind, as Kṛṣṇa captivated the gopīs (Stotram verse 5).</p><p><b>Always.</b> <i>Sadā</i>: not once, not sometimes; His beauty never fades (Prapatti verse 3, "ever new").</p>',
 cards=('💡 Saundarya','Beauty: one of the Lord\'s bodily glories.','💡 Sammohana','Enchanting, captivating the mind.'),
 inner='True beauty draws the heart toward goodness.',
 talk=('Every heart?','Every one! His beauty draws people from everywhere, again and again.'),
 key='Beautiful in every limb, <b>enchanting every heart</b>.'),
D(n='5',lines=M('nityāya niravadyāya','satyānandacidātmane |','sarvāntarātmane śrīmad-','veṅkaṭeśāya maṅgalam',5),theme='THE ETERNAL, INNER SELF OF ALL',
 svg=svg('Many small figures, each with a tiny glowing light inside the heart, all connected to one great light',SUN(110,50,24)+''.join(person(30+40*k,144,'#bcd4f0','#f2c79b',.5)+f'<circle cx="{30+40*k}" cy="{112}" r="4" fill="#ffd60a" stroke="#ff8c1a"/><path d="M110 74 L{30+40*k} 108" stroke="#ffd60a" stroke-width="1.5"/>' for k in range(5)),B),
 mean='Maṅgalam to glorious Veṅkaṭeśa: eternal, flawless, whose very self is truth, bliss and consciousness, the inner Self of all.',
 plain='Blessings to the eternal, perfect Lord Veṅkaṭeśa, who is truth, joy and awareness itself, and who lives within every being.',
 words=[('nityāya','<b>eternal</b>'),('niravadyāya','<b>flawless</b>'),('satya · ānanda · cit','<b>truth</b> · <b>bliss</b> · <b>consciousness</b>'),('ātmane','<b>whose self is</b>'),('sarva-antarātmane','<b>inner Self of all</b>'),('śrīmat','<b>glorious</b>, with Śrī')],
 deep='<p><b>The philosophy.</b> Verses 5–8 turn from beauty to theology. This one gives the Upaniṣadic definition of Brahman: truth, consciousness, bliss.</p><p><b>Antaryāmin.</b> <i>Sarva-antarātman</i>, "inner Self of all": in Rāmānuja\'s Viśiṣṭādvaita, the Lord dwells in every soul and every thing as its inner controller, and the world is like His body.</p><p><b>On the hill and in the heart.</b> The Lord standing on Veṅkaṭa is the same Lord within each of us.</p>',
 cards=('💡 Antaryāmin','"The inner controller": the Lord dwelling within all.','💡 Viśiṣṭādvaita','Rāmānuja\'s philosophy: one Reality, with souls and world as its body.'),
 inner='The Lord you visit on the hill is already within you.',
 talk=('He\'s inside everyone?','As the inner Self of all, says Rāmānuja\'s philosophy. On the hill and in every heart.'),
 key='Truth, bliss, consciousness: <b>the inner Self of all</b>.'),
D(n='6',lines=M('svataḥ sarvavide','sarvaśaktaye sarvaśeṣiṇe |','sulabhāya suśīlāya','veṅkaṭeśāya maṅgalam',6),theme='GREAT, AND YET EASY TO REACH',
 svg=svg('A tall shining Lord bending down to take the hand of a small devotee',LORD(140,.9)+person(60,144,'#ff8c1a','#f2c79b',.55)+'<path d="M76 108 q30 -10 50 -20" stroke="#4a7fd0" stroke-width="5" fill="none"/>'+lab(60,30,'SULABHA',11),B),
 mean='Maṅgalam to Veṅkaṭeśa: all-knowing by His very nature, all-powerful, master of all; and yet easy to reach, and gracious to the lowly.',
 plain='Blessings to Veṅkaṭeśa, who knows everything and can do anything and owns everything, and yet is easy to approach and kind to the humble.',
 words=[('svataḥ','<b>by His own nature</b>'),('sarva-vide','<b>all-knowing</b>'),('sarva-śaktaye','<b>all-powerful</b>'),('sarva-śeṣiṇe','<b>master of all</b>'),('sulabhāya','<b>easy to reach</b>'),('suśīlāya','<b>gracious to the lowly</b>')],
 deep='<p><b>Greatness and nearness.</b> The first three qualities show how great He is; the last two show how near. Śrīvaiṣṇavas cherish this pairing: <i>paratva</i> (supremacy) with <i>saulabhya</i> (accessibility).</p><p><b>Echo of Prapatti verse 2.</b> The same qualities answered our doubts before surrender; now they are celebrated.</p><p><b>Suśīla.</b> One who, though great, mixes freely with the lowly, as Rāma embraced Guha the boatman.</p>',
 cards=('💡 Paratva · Saulabhya','Supremacy and accessibility: the two sides of the Lord.','💡 Guha','The boatman-chief whom Rāma embraced as a friend.'),
 inner='The greatest are those who stay within reach.',
 talk=('All-powerful and easy to reach?','That\'s the wonder. Too great to describe, yet as close as a friend.'),
 key='Knowing all, master of all, <b>and still easy to reach</b>.'),
D(n='7',lines=M('parasmai brahmaṇe','pūrṇakāmāya paramātmane |','prayuñje paratattvāya','veṅkaṭeśāya maṅgalam',7),theme='TO THE SUPREME BRAHMAN',
 svg=svg('A vast night sky with a single shining figure and a full circle of light',
  '<rect width="220" height="160" fill="#0b3d6e"/>'+''.join(f'<circle cx="{(37*k)%220}" cy="{(53*k)%140+6}" r="1.5" fill="#fff"/>' for k in range(30))+'<circle cx="110" cy="80" r="44" fill="none" stroke="#ffd60a" stroke-width="4"/>'+LORD(110,.75).replace('translate(110 0)','translate(110 20)')+lab(110,154,'PARAṂ BRAHMA',10).replace('font-size','fill="#fff" font-size'),B),
 mean='I offer maṅgalam to Veṅkaṭeśa: the Supreme Brahman, whose every desire is fulfilled, the Supreme Self, the Highest Reality.',
 plain='I wish all good to Veṅkaṭeśa, the Supreme, who lacks nothing, the highest Self and the final truth.',
 words=[('parasmai brahmaṇe','<b>to the Supreme Brahman</b>'),('pūrṇa-kāmāya','<b>whose desires are all fulfilled</b>'),('param-ātmane','<b>to the Supreme Self</b>'),('prayuñje','<b>I offer</b>'),('para-tattvāya','<b>to the Highest Reality</b>'),('maṅgalam','<b>auspiciousness</b>')],
 deep='<p><b>"I offer".</b> Here, for once, the poet speaks in the first person: <i>prayuñje</i>, "I offer". He makes his wish personal.</p><p><b>He lacks nothing.</b> <i>Pūrṇa-kāma</i>: all His desires are fulfilled. So why wish Him well? Because love does, regardless. That is the whole spirit of maṅgalāśāsana.</p><p><b>The Brahman on a hill.</b> The Upaniṣads\' Supreme Brahman is the same Lord who stands, in a form we can see, on Veṅkaṭa.</p>',
 cards=('💡 Brahman','The Supreme Reality of the Upaniṣads.','💡 Arcā','The Lord\'s form in a temple image: His most accessible form.'),
 inner='Give to the one who lacks nothing. That is pure love.',
 talk=('Why bless someone who has everything?','Exactly the point! He lacks nothing; we wish Him well purely out of love.'),
 key='"Prayuñje": <b>I offer my blessing to the Supreme</b>.'),
D(n='8',lines=M('ākālatattvam aśrāntam','ātmanām anupaśyatām |','atṛptyamṛtarūpāya','veṅkaṭeśāya maṅgalam',8),theme='NECTAR THAT NEVER SATISFIES',
 svg=svg('Souls gazing at the Lord without rest, with an overflowing cup of nectar that never empties',LORD(150,.8)+crowd(['#bcd4f0','#ff8c1a','#e05a8a'],30,26,146,.45)+'<path d="M60 70 h30 l-4 24 h-22z" fill="#ffd60a" stroke="#111" stroke-width="2"/><path d="M62 70 q14 -14 26 0" fill="#9fd3f0" stroke="#111"/>'+lab(76,110,'AMṚTA',9),B),
 mean='Maṅgalam to Veṅkaṭeśa, who is a nectar that never sates the souls who gaze, without rest and for all time, upon His true nature.',
 plain='Blessings to Veṅkaṭeśa: those who look at Him, forever and without a break, never have enough, like a nectar you can never tire of.',
 words=[('ā-kālam','<b>for all time</b>'),('tattvam','<b>His true nature</b>'),('aśrāntam','<b>without rest</b>'),('anupaśyatām','<b>of those who keep seeing</b>'),('atṛpti','<b>never satisfying</b>'),('amṛta-rūpāya','<b>in the form of nectar</b>')],
 deep='<p><b>Never enough.</b> Most pleasures fade with repetition. This one grows: the more you look, the more you want to look. <i>Atṛpti</i>, "no satiety", is here the highest praise.</p><p><b>The liberated souls.</b> Śrīvaiṣṇava teaching says the freed souls in Vaikuṇṭha enjoy the Lord endlessly. This verse brings that bliss to Tirumala.</p><p><b>Echo.</b> Prapatti verse 3: "ever enjoyed, yet always new."</p>',
 cards=('💡 Anubhava','Experiencing, enjoying the Lord: a key Śrīvaiṣṇava idea.','💡 Nitya-sūri','The eternally free souls who serve the Lord in Vaikuṇṭha.'),
 inner='Some joys grow the more you have them. Seek those.',
 talk=('Doesn\'t anyone get tired of looking?','Never! It\'s nectar you can never have enough of. That\'s why devotees return again and again.'),
 key='A nectar <b>you can never have enough of</b>.'),
D(n='9',lines=M('prāyaḥ svacaraṇau puṃsāṃ','śaraṇyatvena pāṇinā |','kṛpayā\'\'diśate śrīmad-','veṅkaṭeśāya maṅgalam',9),theme='HIS HAND POINTS TO HIS FEET',
 svg=svg('The Lord with his lower right hand pointing down to his feet',
  '<g stroke="#111" stroke-width="2.5"><circle cx="110" cy="34" r="12" fill="#4a7fd0"/><path d="M98 20 h24 v-12 h-24z" fill="#ffd60a"/><path d="M90 124 q-4 -60 20 -76 q24 16 20 76z" fill="#ffd60a"/></g><path d="M126 64 l18 52" stroke="#4a7fd0" stroke-width="6"/><path d="M138 112 l6 8 l4 -10" fill="none" stroke="#111" stroke-width="2"/>'+FEET(110,146,.35)+lab(40,60,'VARADA',10)+lab(40,74,'HASTA',10),B),
 mean='Maṅgalam to glorious Veṅkaṭeśa, who in His mercy points out to people, with His hand, His own two feet as their refuge.',
 plain='Blessings to Veṅkaṭeśa, who kindly points with His hand to His own feet, as if to say: "Here is your refuge."',
 words=[('sva-caraṇau','<b>His own feet</b>'),('puṃsām','<b>to people</b>'),('śaraṇyatvena','<b>as the refuge</b>'),('pāṇinā','<b>with His hand</b>'),('kṛpayā','<b>out of mercy</b>'),('ādiśate','<b>who points out</b>')],
 deep='<p><b>The famous gesture.</b> As in Prapatti verses 10–11: the lower right hand of the image at Tirumala points down to the feet. Tradition reads it as the Lord\'s silent teaching: "surrender here".</p><p><b>Out of mercy.</b> <i>Kṛpayā</i>: He shows the way not because we deserve it, but because He is kind.</p><p><b>For everyone.</b> <i>Puṃsām</i>, "to people": all people, without conditions.</p>',
 cards=('💡 Varada-hasta','A hand gesture of granting; at Tirumala it points to the feet.','💡 Kaṭi-hasta','The left hand on the hip, read as "saṃsāra is only waist-deep".'),
 inner='The answer is shown to everyone. We only need to look where He points.',
 talk=('That hand again!','It\'s the heart of the whole hymn: He points to His feet and says "come here". The Prapatti, the Gītā, and now the blessing.'),
 key='His hand points to <b>His feet, our refuge</b>.'),
D(n='10',lines=M('dayāmṛtataraṅgiṇyās','taraṅgair iva śītalaiḥ |','apāṅgaiḥ siñcate viśvaṃ','veṅkaṭeśāya maṅgalam',10),theme='A GLANCE LIKE COOL WAVES',
 svg=svg('Cool blue waves flowing from the Lord\'s eyes, washing gently over the world',LORD(110,.7).replace('translate(110 0)','translate(110 -14)')+''.join(f'<path d="M{20+20*k} {120+(k%2)*6} q10 -10 20 0" fill="none" stroke="#4aa3df" stroke-width="4"/>' for k in range(9))+'<circle cx="110" cy="146" r="10" fill="#2a9d6f" stroke="#111"/>'+lab(110,22,'DAYĀ',11),B),
 mean='Maṅgalam to Veṅkaṭeśa, who sprinkles the whole world with His sidelong glances, cool like the waves of a river of the nectar of compassion.',
 plain='Blessings to Veṅkaṭeśa, whose kind glances wash over the world like cool waves from a river of mercy.',
 words=[('dayā-amṛta','<b>nectar of compassion</b>'),('taraṅgiṇī','a <b>river</b> (full of waves)'),('taraṅgaiḥ','<b>with waves</b>'),('śītalaiḥ','<b>cool</b>'),('apāṅgaiḥ','<b>with sidelong glances</b>'),('siñcate viśvam','<b>who sprinkles the world</b>')],
 deep='<p><b>Cooling.</b> In a hot land, coolness is the deepest comfort. The Lord\'s glance cools the heat of worldly sorrow.</p><p><b>A sidelong look.</b> <i>Apāṅga</i>, the corner of the eye. Even a passing glance from Him is a wave of mercy: compare the teacher\'s glance in Prapatti verse 15.</p><p><b>The whole world.</b> <i>Viśvam</i>: no one is left dry.</p>',
 cards=('💡 Kaṭākṣa','The Lord\'s sidelong glance of grace.','💡 Dayā','Compassion: Vedānta Deśika wrote a hundred verses on Veṅkaṭeśa\'s dayā (Dayā-śatakam).'),
 inner='A kind look is a gift. Give it freely.',
 talk=('Just a glance?','Even a glance from Him is a cool wave of mercy, and it reaches the whole world.'),
 key='His glance: <b>cool waves of mercy over the world</b>.'),
D(n='11',lines=M('sragbhūṣāmbarahetīnāṃ','suṣamāvahamūrtaye |','sarvārtiśamanāyāstu','veṅkaṭeśāya maṅgalam',11),theme='HE ADORNS HIS ORNAMENTS',
 svg=svg('A flower garland, jewels, silk cloth, a conch and discus all glowing more brightly because they are on the Lord',LORD(110,.9)+'<path d="M88 64 q22 40 44 0" fill="none" stroke="#f08aa6" stroke-width="6"/>'+'<circle cx="40" cy="60" r="12" fill="#fff" stroke="#111" stroke-width="2"/><circle cx="180" cy="60" r="12" fill="#ffd60a" stroke="#111" stroke-width="2"/>'+lab(40,86,'ŚAṄKHA',8)+lab(180,86,'CAKRA',8),B),
 mean='May there be maṅgalam for Veṅkaṭeśa, whose form lends beauty to His garlands, ornaments, garments and weapons, and who calms every sorrow.',
 plain='Blessings to Veṅkaṭeśa, who makes His garlands, jewels, clothes and weapons look beautiful, and who takes away every pain.',
 words=[('srak','<b>garland</b>'),('bhūṣā','<b>ornaments</b>'),('ambara','<b>garments</b>'),('heti','<b>weapons</b>'),('suṣamā-āvaha','<b>bringing beauty</b>'),('sarva-ārti-śamanāya','<b>who calms every sorrow</b>')],
 deep='<p><b>The reverse of usual.</b> We wear ornaments to look better. The Lord makes the ornaments look better. His beauty flows into them.</p><p><b>Weapons too.</b> Conch and discus are beautiful on Him: power in His hands is never ugly, because it protects.</p><p><b>Calming sorrow.</b> <i>Sarvārti-śamana</i>: the sight of Him soothes every pain. Pilgrims often speak of this.</p>',
 cards=('💡 Alaṅkāra','Adornment of the deity, a major part of temple worship.','💡 Āyudha','The Lord\'s weapons: conch, discus, mace, bow, sword.'),
 inner='A good person makes their surroundings better, not the other way round.',
 talk=('He makes jewels look good?','Normally jewels make us look good. With Him, it\'s the other way around!'),
 key='He adorns His ornaments, <b>and calms every sorrow</b>.'),
D(n='12',lines=M('śrīvaikuṇṭhaviraktāya','svāmipuṣkariṇītaṭe |','ramayā ramamāṇāya','veṅkaṭeśāya maṅgalam',12),theme='HE PREFERRED TIRUMALA TO VAIKUṆṬHA',
 svg=svg('The Lord and Lakshmi happily walking by a temple tank, with a distant heavenly palace on clouds behind them',
  '<path d="M150 30 q10 -20 30 -10 q20 -10 30 10 q10 20 -10 20 h-40 q-20 0 -10 -20z" fill="#fff" stroke="#111" stroke-width="2"/>'+lab(180,40,'VAIKUṆṬHA',7)+'<rect x="0" y="124" width="220" height="36" fill="#4aa3df" stroke="#111" stroke-width="2"/>'+LORD(80,.6).replace('translate(80 0)','translate(80 40)')+person(120,124,'#e05a8a','#f2c79b',.55)+lab(110,146,'SVĀMI PUṢKARIṆĪ',8),B),
 mean='Maṅgalam to Veṅkaṭeśa, who lost interest in His own Vaikuṇṭha, and delights with Ramā on the bank of the Svāmi Puṣkariṇī.',
 plain='Blessings to Veṅkaṭeśa, who left even heaven behind to be happy with Lakṣmī here, beside the temple tank at Tirumala.',
 words=[('vaikuṇṭha','the Lord\'s <b>heaven</b>'),('viraktāya','<b>who lost interest in</b>'),('svāmi-puṣkariṇī','the <b>Lord\'s tank</b> at Tirumala'),('taṭe','<b>on the bank</b>'),('ramayā','<b>with Ramā</b> (Lakṣmī)'),('ramamāṇāya','<b>who delights</b>')],
 deep='<p><b>Earth over heaven.</b> In Suprabhātam verse 20, people preferred earth after seeing His tower. Now the Lord Himself prefers Tirumala to Vaikuṇṭha!</p><p><b>The legend.</b> The Purāṇic story says Viṣṇu came down to the Veṅkaṭa hill and settled by the Svāmi Puṣkariṇī. Tirumala is called <b>Bhū-Vaikuṇṭha</b>, "Vaikuṇṭha on earth".</p><p><b>Ramayā ramamāṇa.</b> A lovely sound-play: "delighting (ramamāṇa) with Ramā". He is never without Her, here as in heaven.</p>',
 cards=('💡 Bhū-Vaikuṇṭha','"Vaikuṇṭha on earth": a name for Tirumala.','💡 Svāmi Puṣkariṇī','The sacred tank beside the temple (Suprabhātam verse 14).'),
 inner='The Lord chose to come close. Meet Him where He came.',
 talk=('He preferred earth to heaven?','So the verse says! That\'s why Tirumala is called Vaikuṇṭha on earth.'),
 key='He left Vaikuṇṭha to <b>delight with Lakṣmī on the Seven Hills</b>.'),
D(n='13',lines=M('śrīmatsundarajāmātṛ-','munimānasavāsine |','sarvalokanivāsāya','śrīnivāsāya maṅgalam',13),theme='WHO LIVES IN MY TEACHER\'S HEART',
 svg=svg('A sage in meditation with the Lord shown small inside his heart, and around him the whole world',person(110,146,'#ff8c1a','#f2c79b',.9)+'<circle cx="110" cy="110" r="14" fill="#fff8c0" stroke="#111" stroke-width="2"/>'+LORD(110,.18).replace('translate(110 0)','translate(110 96)')+'<circle cx="110" cy="80" r="72" fill="none" stroke="#4aa3df" stroke-width="3" stroke-dasharray="6 4"/>'+lab(110,22,'MAṆAVĀḶA MĀMUNI',9),B),
 mean='Maṅgalam to Śrīnivāsa, who dwells in the heart of the glorious sage Sundara Jāmātṛ Muni, and in whom all the worlds dwell.',
 plain='Blessings to Śrīnivāsa, who lives in the heart of my teacher Maṇavāḷa Māmuni, and in whom the whole world lives.',
 words=[('sundara-jāmātṛ-muni','<b>Maṇavāḷa Māmuni</b>'),('mānasa-vāsine','<b>who dwells in the mind</b>'),('sarva-loka','<b>all worlds</b>'),('nivāsāya','<b>to the dwelling of</b>'),('śrī-nivāsāya','<b>to Śrīnivāsa</b>'),('śrīmat','<b>glorious</b>')],
 deep='<p><b>The teacher again.</b> As in Prapatti verse 15, the poet names his ācārya, here as <i>Sundara Jāmātṛ Muni</i>, another Sanskrit form of Maṇavāḷa Māmuni ("beautiful bridegroom sage").</p><p><b>Two dwellings.</b> The whole world dwells in Him; and He dwells in the heart of a devotee. The infinite fits inside a loving heart.</p><p><b>Three "nivāsas".</b> Śrī-nivāsa, sarva-loka-nivāsa, and the one who dwells in the muni\'s mind: the Lord is a home, and has a home.</p>',
 cards=('💡 Jāmātṛ','"Son-in-law, bridegroom": Sanskrit for Tamil maṇavāḷan.','💡 Ācārya-bhakti','Devotion to one\'s teacher, central in Śrīvaiṣṇava practice.'),
 inner='Make your heart a home where the Lord would want to live.',
 talk=('God lives in the teacher\'s heart?','The one in whom all worlds live chooses to live in a devotee\'s heart. What an honour!'),
 key='All worlds live in Him; <b>He lives in a devotee\'s heart</b>.'),
D(n='14',lines=M('maṅgalāśāsanaparair','madācāryapurogamaiḥ |','sarvaiś ca pūrvair ācāryaiḥ','satkṛtāyāstu maṅgalam',14),theme='AS ALL OUR TEACHERS HAVE BLESSED HIM',
 svg=svg('A long line of teachers through the ages, each holding a lamp toward the Lord on the hill',HILL+TEMPLE(190,84,.8)+''.join(person(20+28*k,146-4*k,'#ff8c1a' if k%2 else '#fff','#f2c79b',.42)+LAMP(32+28*k,112-4*k,.4) for k in range(6))+lab(80,26,'GURU-PARAMPARĀ',10),B),
 mean='May there be maṅgalam for the Lord honoured by all the earlier teachers, led by my own teacher, all devoted to wishing Him well.',
 plain='May all be well with the Lord, as my teacher and all the teachers before him have wished, generation after generation.',
 words=[('maṅgala-āśāsana-paraiḥ','<b>devoted to blessing Him</b>'),('mat-ācārya','<b>my teacher</b>'),('purogamaiḥ','<b>led by</b>'),('pūrvaiḥ ācāryaiḥ','<b>by earlier teachers</b>'),('satkṛtāya','<b>to the one honoured</b>'),('astu maṅgalam','<b>may it be auspicious</b>')],
 deep='<p><b>Joining a long line.</b> The poet does not bless the Lord alone: he joins a chain of teachers, from Rāmānuja and the Āḻvārs down to his own guru, who all blessed the Lord in the same way.</p><p><b>Guru-paramparā.</b> The lineage of teachers is central to Śrīvaiṣṇava life; every recitation is done "in their footsteps".</p><p><b>The last word.</b> The whole 70-verse hymn ends with <i>maṅgalam</i>: "may all be well." From "kausalyā suprajā rāma" to this blessing, a single morning has become a whole life of devotion.</p>',
 cards=('💡 Guru-paramparā','The unbroken line of teachers handing on the tradition.','💡 Pūrvācāryas','"The earlier teachers": the Āḻvārs, Rāmānuja and their successors.'),
 inner='We pray in the footsteps of all who prayed before us.',
 talk=('Is that the end of the Suprabhātam?','The very last verse of all seventy! It ends where love always ends: "May all be well with You."'),
 key='As all our teachers did: <b>maṅgalam to the Lord</b>.'),
]
